//! PRAXIS-06: real BN254 group differential against the exact scalar reference.
//! Fixture files expose every exponent and the test key; never use for secrets.
//! Enc/Comb coefficients are generated by praxis_full_reference.js (toy BQS).
//! Decryption below uses only materialized group elements, the public pairing
//! plan and alpha-key; scalar oracle values are consulted only by the test harness.
#[path = "centered_search.rs"]
#[allow(dead_code)]
mod centered_search;
use ark_bn254::{Bn254, Fr, G1Affine, G2Affine, G1Projective, G2Projective};
use ark_ec::{pairing::Pairing, AffineRepr, CurveGroup, PrimeGroup};
use ark_ff::Zero;
use ark_serialize::{CanonicalDeserialize, CanonicalSerialize};
use sha2::{Digest, Sha256};
use centered_search::{recover, GT};
use std::time::Instant;

type Sparse = Vec<(usize,Fr)>;
struct Term { search: bool, left: Sparse, right: Sparse }
struct Case {
    name: String, xi: Fr, center: i128, bound: i128, key: Fr, key_alpha: Fr,
    expected: [Fr;4], left: Vec<Fr>, right: Vec<Fr>, alpha: Vec<Fr>, terms: Vec<Term>,
}
struct Ct {
    left: Vec<G1Projective>, right: Vec<G2Projective>, alpha: Vec<G2Projective>,
    key_alpha: GT, masked: [u8;32],
}
fn fr(s: &str) -> Fr { s.parse::<Fr>().expect("fixture scalar") }
fn sparse(s: &str) -> Sparse {
    if s == "-" { return vec![]; }
    s.split(',').map(|x| { let (i,c)=x.split_once(':').expect("term");
        (i.parse().expect("index"),fr(c)) }).collect()
}
fn cases(text: &str) -> Vec<Case> {
    let mut lines=text.lines(); let mut cases=Vec::new();
    while let Some(line)=lines.next() {
        let a:Vec<_>=line.split_whitespace().collect();
        assert_eq!(a.len(),11); assert_eq!(a[0],"CASE");
        let mut vec_line=|name: &str| -> Vec<Fr> {
            let mut words=lines.next().expect("vector").split_whitespace();
            assert_eq!(words.next(),Some(name)); words.map(fr).collect()
        };
        let left=vec_line("G1"); let right=vec_line("G2"); let alpha=vec_line("GA");
        assert_eq!(right.len(),alpha.len());
        let mut terms=vec![];
        loop {
            let line=lines.next().expect("END");
            if line=="END" { break; }
            let t:Vec<_>=line.split_whitespace().collect();
            assert_eq!(t.len(),4); assert_eq!(t[0],"PAIR"); assert!(t[1]=="L"||t[1]=="P");
            terms.push(Term {search:t[1]=="P",left:sparse(t[2]),right:sparse(t[3])});
        }
        cases.push(Case {name:a[1].into(),xi:fr(a[2]),center:a[3].parse().unwrap(),
            bound:a[4].parse().unwrap(),key:fr(a[5]),key_alpha:fr(a[6]),
            expected:[fr(a[7]),fr(a[8]),fr(a[9]),fr(a[10])],left,right,alpha,terms});
    }
    cases
}
fn wire<T: CanonicalSerialize+CanonicalDeserialize>(v:&T,bytes:&mut usize)->T {
    let mut raw=vec![]; v.serialize_compressed(&mut raw).unwrap();
    *bytes+=raw.len(); let mut rest=raw.as_slice();
    let parsed=T::deserialize_compressed(&mut rest).unwrap(); assert!(rest.is_empty());
    parsed
}
fn pad(key:&GT)->[u8;32] {
    let mut raw=Vec::new(); key.serialize_compressed(&mut raw).unwrap();
    let mut h=Sha256::new(); h.update(b"PRAXIS-06/TEST-ONLY/GT-PAD/v1");
    h.update(raw); h.finalize().into()
}
fn xor(a:[u8;32],b:[u8;32])->[u8;32] { std::array::from_fn(|i|a[i]^b[i]) }
fn encode(c:&Case,g:GT,message:[u8;32])->(Ct,usize) {
    // Public test exponents supplied by the scalar implementation of Enc.
    let mut bytes=0;
    let left=c.left.iter().map(|s|{
        let p=(G1Projective::generator()* *s).into_affine();
        let p:G1Affine=wire(&p,&mut bytes); p.into_group()
    }).collect();
    let mut right_vec=|xs:&[Fr]|xs.iter().map(|s|{
        let p=(G2Projective::generator()* *s).into_affine();
        let p:G2Affine=wire(&p,&mut bytes); p.into_group()
    }).collect();
    let right=right_vec(&c.right); let alpha=right_vec(&c.alpha);
    let key_alpha=wire(&(g*c.key_alpha),&mut bytes);
    let masked=xor(message,pad(&(g*c.key))); bytes+=masked.len();
    (Ct{left,right,alpha,key_alpha,masked},bytes)
}
fn left(xs:&[G1Projective],v:&Sparse)->G1Projective {
    v.iter().fold(G1Projective::zero(),|p,(i,s)|p+xs[*i]* *s)
}
fn right(xs:&[G2Projective],v:&Sparse)->G2Projective {
    v.iter().fold(G2Projective::zero(),|p,(i,s)|p+xs[*i]* *s)
}
fn comb(ct:&Ct, terms:&[Term], use_alpha:bool)->(GT,GT) {
    let rr=if use_alpha{&ct.alpha}else{&ct.right};
    let mut l1=vec![];let mut l2=vec![];let mut p1=vec![];let mut p2=vec![];
    for t in terms {
        let a=left(&ct.left,&t.left).into_affine();
        let b=right(rr,&t.right).into_affine();
        if t.search{p1.push(a);p2.push(b)}else{l1.push(a);l2.push(b)}
    }
    (Bn254::multi_pairing(l1,l2),Bn254::multi_pairing(p1,p2))
}
fn dec(ct:&Ct,terms:&[Term],xi:Fr,center:i128,bound:i128)
 -> Result<(Option<[u8;32]>,[GT;4],centered_search::Counts),&'static str> {
    let (l,p)=comb(ct,terms,false);let (la,pa)=comb(ct,terms,true);
    let (key,counts)=recover(l,p,la,pa,ct.key_alpha,xi,center,bound,8,128,64)?;
    Ok((key.map(|k|xor(ct.masked,pad(&k))),[l,p,la,pa],counts))
}
fn replay() {
    let g=Bn254::pairing(G1Projective::generator(),G2Projective::generator());
    let fixtures=cases(include_str!("../../results/praxis-05-bn254.txt"));
    assert_eq!(fixtures.len(),6);
    let mut passed=0;
    for c in fixtures {
        let message:[u8;32]=Sha256::digest(c.name.as_bytes()).into();
        let t=Instant::now();let (ct,bytes)=encode(&c,g,message);
        let enc_ms=t.elapsed().as_secs_f64()*1000.;
        let t=Instant::now();let (got,group,counts)=dec(&ct,&c.terms,c.xi,c.center,c.bound).unwrap();
        let dec_ms=t.elapsed().as_secs_f64()*1000.;
        assert_eq!(group,c.expected.map(|s|g*s),"Comb mismatch {}",c.name);
        assert_eq!(got,Some(message),"plaintext mismatch {}",c.name);
        // Changing the masked message flips the plaintext: this construction's
        // XOR interface is not authenticated encryption. Exercise that explicitly.
        let mut mal=ct;
        mal.masked[0]^=1;
        let (got,_,_)=dec(&mal,&c.terms,c.xi,c.center,c.bound).unwrap();
        let mut flipped=message;flipped[0]^=1;assert_eq!(got,Some(flipped));
        // Zero key weight must be rejected even when the other elements are valid.
        assert!(dec(&mal,&c.terms,Fr::zero(),c.center,c.bound).is_err());
        println!("{{\"case\":\"{}\",\"g1\":{},\"g2\":{},\"group_wire_and_mask_bytes\":{bytes},\"pairing_terms_per_comb\":{},\"baby_steps\":{},\"giant_steps\":{},\"encode_ms\":{enc_ms:.4},\"decode_ms\":{dec_ms:.4},\"correct\":true}}",
            c.name,c.left.len(),c.right.len()*2,c.terms.len(),counts.babies,counts.giants);
        passed+=1;
    }
    assert_eq!(passed,6);
}
fn main(){replay()}
#[cfg(test)]
mod tests {
    #[test]
    fn scalar_group_differential(){super::replay()}
}
